<template><SuperAdminLayout><template v-if="calendar"><main class="calendar"><header><div><h1>Calendar</h1><p>View and manage important dates, events, and scheduled items.</p></div><div class="actions"><button @click="today">Today</button><button class="primary" @click="openForm()">＋ New Event</button></div></header><section class="metrics"><article v-for="x in metrics" :key="x.label" :class="x.color"><i>{{x.icon}}</i><span><b>{{x.label}}</b><strong>{{x.value}}</strong><small>{{x.caption}}</small></span></article></section><section class="layout"><article class="month"><div class="toolbar"><div><button @click="move(-1)">‹</button><button @click="move(1)">›</button></div><h2>{{label}}</h2><input type="month" v-model="monthValue"></div><div class="week"><b v-for="d in names" :key="d">{{d}}</b></div><div class="grid"><div v-for="d in days" :key="d.key" class="day" :class="{off:!d.current,now:d.key===todayKey}"><b>{{d.date.getDate()}}</b><button v-for="e in d.events.slice(0,3)" :key="e.id" class="event" :class="tone(e)" @click="openForm(e)">{{e.title}}<small>{{eventTime(e)}}</small></button><small v-if="d.events.length>3">+{{d.events.length-3}} more</small></div></div></article><aside><header><h2>Upcoming Events</h2><button @click="openForm()">Add Event</button></header><p v-if="!upcoming.length" class="empty">No upcoming events.</p><button v-for="e in upcoming" :key="e.id" class="upcoming" @click="openForm(e)"><i :class="tone(e)">{{icon(e)}}</i><span><b>{{e.title}}</b><small>{{e.description||e.type||'Scheduled platform event'}}</small></span><time>{{eventDate(e)}}<br>{{eventTime(e)}}</time></button></aside></section></main><div v-if="showForm" class="modal" @click.self="showForm=false"><form @submit.prevent="save"><header><div><p>2. CALENDAR</p><h2>{{editing?'Edit Event':'New Event'}}</h2></div><button type="button" class="close" @click="showForm=false">×</button></header><section><h3>ⓘ 1) Event Info</h3><div class="formgrid"><label>Subject *<input v-model="form.title" required></label><label>Status *<select v-model="form.status"><option value="scheduled">Active</option><option value="cancelled">Inactive</option></select></label><label class="wide">Description<textarea v-model="form.description"></textarea></label></div></section><section><h3>▣ 2) Date & Time</h3><div class="formgrid dates"><label>Start Date *<input v-model="form.startDate" type="date" required></label><label>Start Time *<input v-model="form.startTime" type="time" :disabled="form.allDay" required></label><label>End Date<input v-model="form.endDate" type="date"></label><label>End Time<input v-model="form.endTime" type="time" :disabled="form.allDay"></label><label class="check"><input v-model="form.allDay" type="checkbox"> All Day</label></div></section><section><h3>⟳ 3) Event Options</h3><div class="formgrid"><label>Event Type<select v-model="form.type"><option>general</option><option>payment</option><option>announcement</option><option>maintenance</option><option>support</option><option>customer</option></select></label><label>Priority<select v-model="form.priority"><option>low</option><option>medium</option><option>high</option><option>critical</option></select></label><label>Repeat<select v-model="form.repeat"><option value="">Single Event</option><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select></label></div></section><footer><button type="button" @click="showForm=false">Cancel</button><button class="primary" :disabled="saving">{{saving?'Saving…':'▣ Save Event'}}</button></footer></form></div></template><template v-else><h1>Announcements</h1><section class="plain"><p v-for="i in items" :key="i.id"><b>{{i.title}}</b> — {{i.body}}</p></section></template></SuperAdminLayout></template>
<script setup>import{computed,onMounted,ref,watch}from'vue';import{useRoute}from'vue-router';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';const route=useRoute(),calendar=computed(()=>route.meta.kind==='calendar'),items=ref([]),showForm=ref(false),editing=ref(null),saving=ref(false),now=new Date(),view=ref(new Date(now.getFullYear(),now.getMonth(),1)),names=['SUN','MON','TUE','WED','THU','FRI','SAT'],dateKey=d=>new Date(d).toISOString().slice(0,10),todayKey=dateKey(now),blank=()=>({title:'',description:'',status:'scheduled',startDate:todayKey,startTime:'09:00',endDate:'',endTime:'',allDay:false,type:'general',priority:'medium',repeat:''}),form=ref(blank());const monthValue=computed({get:()=>`${view.value.getFullYear()}-${String(view.value.getMonth()+1).padStart(2,'0')}`,set:v=>{let[a,b]=v.split('-');view.value=new Date(+a,+b-1,1)}}),label=computed(()=>new Intl.DateTimeFormat('en',{month:'long',year:'numeric'}).format(view.value)),events=computed(()=>items.value.map(e=>({...e,start:new Date(e.start_at),end:e.end_at?new Date(e.end_at):null})).filter(e=>!isNaN(e.start))),days=computed(()=>{let first=new Date(view.value);first.setDate(1-first.getDay());return Array.from({length:42},(_,i)=>{let d=new Date(first);d.setDate(first.getDate()+i);let key=dateKey(d);return{date:d,key,current:d.getMonth()===view.value.getMonth(),events:events.value.filter(e=>dateKey(e.start)===key)}})}),upcoming=computed(()=>events.value.filter(e=>e.start>=new Date(new Date().setHours(0,0,0,0))).sort((a,b)=>a.start-b.start).slice(0,8)),metrics=computed(()=>[{label:'Scheduled Payments',icon:'$',color:'blue',caption:'This Month',value:count('payment')},{label:'Announcements',icon:'◉',color:'green',caption:'This Month',value:count('announce')},{label:'New Account Reviews',icon:'♙',color:'orange',caption:'Pending',value:count('account')},{label:'Customer Follow-Ups',icon:'♧',color:'purple',caption:'This Month',value:count('customer')},{label:'System Maintenance',icon:'⚒',color:'red',caption:'This Month',value:count('mainten')},{label:'Support Reminders',icon:'◖',color:'blue',caption:'This Month',value:count('support')}]);function count(x){return events.value.filter(e=>`${e.title} ${e.type||e.event_type||''}`.toLowerCase().includes(x)).length}function move(n){view.value=new Date(view.value.getFullYear(),view.value.getMonth()+n,1)}function today(){view.value=new Date(now.getFullYear(),now.getMonth(),1)}function tone(e){let s=`${e.title} ${e.type||e.event_type||''}`.toLowerCase();return s.includes('mainten')?'red':s.includes('announce')?'green':s.includes('account')?'orange':s.includes('customer')?'purple':'blue'}function icon(e){return{red:'⚒',green:'◉',orange:'♙',purple:'♧',blue:'$'}[tone(e)]}function eventTime(e){return e.all_day?'All day':new Intl.DateTimeFormat('en',{hour:'numeric',minute:'2-digit'}).format(e.start)}function eventDate(e){return new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(e.start)}function openForm(e=null){editing.value=e;if(e)form.value={title:e.title,description:e.description||'',status:e.status||'scheduled',startDate:dateKey(e.start),startTime:e.start.toTimeString().slice(0,5),endDate:e.end?dateKey(e.end):'',endTime:e.end?e.end.toTimeString().slice(0,5):'',allDay:!!e.all_day,type:e.type||e.event_type||'general',priority:e.priority||'medium',repeat:e.recurrence_freq||''};else form.value=blank();showForm.value=true}async function load(){let{data}=await client.get(calendar.value?'/super-admin/calendar':'/super-admin/announcements');items.value=data.data||[]}async function save(){saving.value=true;try{let f=form.value,p={title:f.title,description:f.description,status:f.status,all_day:f.allDay,start_at:`${f.startDate}T${f.allDay?'00:00':f.startTime}:00`,end_at:f.endDate?`${f.endDate}T${f.allDay?'23:59':f.endTime||f.startTime}:00`:null,visibility:'company',event_type:f.type,priority:f.priority,recurrence_freq:f.repeat||null,recurrence_mode:'none'};if(editing.value)await client.put(`/calendar-events/${editing.value.id}`,p);else await client.post('/calendar-events',p);showForm.value=false;await load()}finally{saving.value=false}}onMounted(load);watch(()=>route.meta.kind,load)</script>
<style scoped>.calendar{color:#07194b}.calendar>header{display:flex;justify-content:space-between;margin-bottom:25px}.calendar h1{font-size:2.6rem;margin:0}.calendar p{color:#4b6190;margin:7px 0}.actions,form footer{display:flex;gap:10px}button{cursor:pointer;border:1px solid #cfdaea;border-radius:7px;background:#fff;padding:9px 14px;color:#092154;font-weight:700}.primary{background:#0957e8;color:white;border-color:#0957e8}.metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:16px;margin-bottom:17px}.metrics article{display:flex;align-items:center;gap:12px;min-height:100px;padding:14px;border:1px solid #e0e7f1;border-radius:10px}.metrics i,.upcoming i{display:grid;place-items:center;border-radius:50%;width:43px;height:43px;font-size:1.4rem;font-style:normal}.metrics b,.metrics small,.metrics strong{display:block}.metrics b,.metrics small{font-size:.76rem}.metrics strong{font-size:2rem}.blue i,.blue strong{color:#0757ef;background:#edf4ff}.green i,.green strong{color:#008b38;background:#eef9f0}.orange i,.orange strong{color:#e85a00;background:#fff1e8}.purple i,.purple strong{color:#5924e7;background:#f3efff}.red i,.red strong{color:#ef1c2d;background:#ffedef}.layout{display:grid;grid-template-columns:2.1fr 1fr;gap:17px}.month,aside,.plain{border:1px solid #e0e6f0;border-radius:10px;overflow:hidden}.toolbar{height:67px;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:0 18px;border-bottom:1px solid #e1e7f1}.toolbar h2{margin:0;font-size:1.45rem}.toolbar button{font-size:1.4rem;padding:2px 12px;margin-right:7px}.toolbar input{justify-self:end;border:1px solid #d6dfed;border-radius:6px;padding:8px;color:#092154}.week,.grid{display:grid;grid-template-columns:repeat(7,1fr)}.week b{text-align:center;padding:10px 0;border-bottom:1px solid #e1e7f1;font-size:.72rem}.day{min-height:100px;padding:8px;border-right:1px solid #e6ebf2;border-bottom:1px solid #e6ebf2;font-size:.82rem}.off>b{color:#9eacc8}.now>b{display:grid;place-items:center;width:25px;height:25px;background:#0757eb;color:white;border-radius:50%}.event{display:block;width:100%;margin-top:6px;padding:5px;border:0;text-align:left;font-size:.64rem}.event small{display:block;margin-top:2px}.event.blue{background:#edf4ff;color:#0757e9}.event.green{background:#edf9f0;color:#087a38}.event.orange{background:#fff1e8;color:#d95700}.event.purple{background:#f3efff;color:#5220dd}.event.red{background:#ffedf0;color:#df1929}aside header{display:flex;justify-content:space-between;align-items:center;padding:15px 19px;border-bottom:1px solid #e1e7f1}aside h2{margin:0;font-size:1.1rem}aside header button{border:0;padding:0;color:#0757e9}.upcoming{display:flex;gap:12px;align-items:center;width:100%;padding:14px 18px;border:0;border-bottom:1px solid #edf0f5;text-align:left}.upcoming i{flex:0 0 35px;width:35px;height:35px}.upcoming span{flex:1;min-width:0}.upcoming b,.upcoming small{display:block}.upcoming b{font-size:.82rem}.upcoming small{font-size:.69rem;color:#51648c;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.upcoming time{text-align:right;font-size:.68rem;color:#294778}.empty{padding:26px;text-align:center}.modal{position:fixed;z-index:99;inset:0;padding:22px;background:#06163577;display:grid;place-items:center}.modal form{width:min(960px,100%);max-height:94vh;overflow:auto;background:#fff;border-radius:12px;padding:24px}.modal form>header{display:flex;justify-content:space-between}.modal h2,.modal h3{margin:4px 0 14px}.modal header p{margin:0;color:#0757e9;font-size:.72rem;font-weight:bold}.close{border:0;font-size:2rem;padding:0}.modal section{border:1px solid #d9e2ef;border-radius:9px;padding:14px;margin:9px 0}.formgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.dates{grid-template-columns:repeat(5,1fr)}label{font-size:.78rem;font-weight:bold}input,select,textarea{box-sizing:border-box;width:100%;margin-top:5px;padding:9px;border:1px solid #bbc9dd;border-radius:6px;font:inherit}.wide{grid-column:1/-1}textarea{height:72px}.check{align-self:end;padding:9px}.check input{width:auto;margin-right:6px}.modal footer{justify-content:flex-end;margin-top:15px}.plain{padding:20px}@media(max-width:1200px){.metrics{grid-template-columns:repeat(3,1fr)}.layout{grid-template-columns:1fr}}@media(max-width:700px){.calendar>header{display:block}.actions{margin-top:12px}.metrics{grid-template-columns:1fr 1fr}.day{min-height:76px;padding:4px}.event{font-size:.5rem;padding:3px}.toolbar{grid-template-columns:1fr auto}.toolbar h2{grid-column:1/-1}.toolbar input{display:none}.formgrid,.dates{grid-template-columns:1fr}}</style>
